import {repository,mergeReportBackup} from '../precheck/store.mjs';
import {planMerge} from './backup-model.mjs';
import {normalizeSettings} from './settings-model.mjs';
export const storageKeys={projects:'paperknow-projects',drafts:'paperknow-drafts',literature:'paperknow-literature',tasks:'paperknow-local-tasks',profile:'paperknow-local-profile',preferences:'paperknow-preferences',moreFavorites:'paperknow-more-favorites'};
export async function currentBackup(storage=localStorage){const [reports,sources]=await Promise.all([repository.all('reports'),repository.all('sources')]);const result={reports,sources};for(const [key,name]of Object.entries(storageKeys)){const raw=storage.getItem(name);try{result[key]=raw?JSON.parse(raw):(['profile','preferences'].includes(key)?{}:[]);}catch{throw Error('当前本地数据无法读取，请先保留原始备份。');}if(!['profile','preferences'].includes(key)&&!Array.isArray(result[key]))throw Error('当前本地数据结构异常。');}return result;}
export const fingerprint=data=>JSON.stringify(data);
export async function restoreBackup(incoming,expected,{restorePersonal=false,storage=localStorage}={}){const before=await currentBackup(storage);if(fingerprint(before)!==expected)throw Error('本地记录已变化，请重新预览备份。');const snapshot=new Map(Object.values(storageKeys).map(key=>[key,storage.getItem(key)]));let touched=false;try{await mergeReportBackup(incoming.reports,(latest,latestSources)=>{const fresh={...before,reports:latest,sources:latestSources};if(fingerprint(fresh)!==expected)throw Error('报告记录已变化，请重新预览备份。');for(const [key,name]of Object.entries(storageKeys))if(storage.getItem(name)!==snapshot.get(name))throw Error('本地记录已变化，请重新预览备份。');const plan=planMerge(fresh,incoming);touched=true;for(const key of ['projects','drafts','literature','tasks'])storage.setItem(storageKeys[key],JSON.stringify(plan.merged[key]));storage.setItem(storageKeys.moreFavorites,JSON.stringify([...new Set([...before.moreFavorites,...incoming.moreFavorites])]));if(restorePersonal){if(incoming.profile)storage.setItem(storageKeys.profile,JSON.stringify({...before.profile,...incoming.profile}));if(incoming.preferences)storage.setItem(storageKeys.preferences,JSON.stringify({...before.preferences,...normalizeSettings(incoming.preferences)}));}},incoming.sources||[]);}catch(error){if(touched){try{for(const [key,value]of snapshot){if(value===null)storage.removeItem(key);else storage.setItem(key,value);}}catch{throw Error('恢复失败，部分本地记录可能已写入；请保留备份并检查当前内容。');}}throw error;}return planMerge(before,incoming).summary;}
